/* @socom-skeleton stub UpdateFrustum__Q23zdb7CCameraFv */
/* @socom-skeleton stub UpdateFrustum__Q23zdb7CCameraFv */
void zdb::CCamera::UpdateFrustum()
{
	/* 0x1e5180: the view pyramid out to the far plane in world space - m_frustum is the
	   eye and the two far corners on the horizon, m_fullfrustum the eye and the four far
	   corners - then the full one reduced to its convex hull in x/z (the grid walks it) */
	f32 halfX = m_far_plane * m_tan.x;
	CPnt3D* eye = reinterpret_cast<CPnt3D*>(m_matrix.m_matrix[3]);

	m_frustum[0] = *eye;
	m_frustum[1] = CPnt3D(halfX, 0.0f, -m_far_plane);
	m_frustum[2] = CPnt3D(-halfX, 0.0f, -m_far_plane);
	m_matrix.Transform(&m_frustum[1], 2);

	f32 halfY = m_far_plane * m_tan.y;

	m_fullfrustum[0] = *eye;
	m_fullfrustum[1] = CPnt3D(halfX, -halfY, -m_far_plane);
	m_fullfrustum[2] = CPnt3D(-halfX, -halfY, -m_far_plane);
	m_fullfrustum[3] = CPnt3D(halfX, halfY, -m_far_plane);
	m_fullfrustum[4] = CPnt3D(-halfX, halfY, -m_far_plane);
	m_matrix.Transform(&m_fullfrustum[1], 4);

	m_fullfrustum_points = 5;
	m_fullfrustum_points = find_convex_hull_xz(m_fullfrustum, m_fullfrustum_points);
}

/* @socom-skeleton stub find_convex_hull_xz__Q23zdb7CCameraFP6CPnt3Di */
/* @socom-skeleton stub find_convex_hull_xz__Q23zdb7CCameraFP6CPnt3Di */
int zdb::CCamera::find_convex_hull_xz(CPnt3D *points, int count)
{
	/* 0x1e4f00: gift wrapping in x/z with theta_x_z's pseudo-angle. Starts from the point
	   of greatest z (ties: least x), uses points[count] as the closing sentinel (so the
	   array holds count + 1 points), sorts the hull to the front and returns its size
	   (0 if it never closes). */
	int next = 0;

	for (int i = 1; i < count; i++)
	{
		if (!(points[i].z <= points[next].z) || (points[i].z == points[next].z && points[i].x < points[next].x))
			next = i;
	}

	points[count] = points[next];
	f32 angle = 0.0f;

	for (int m = 0; m < count; m++)
	{
		CPnt3D swap = points[m];
		points[m] = points[next];
		points[next] = swap;

		next = count;
		f32 minAngle = angle;
		f32 best = 4.0f;
		f32 bestDist = 0.0f;

		for (int i = m + 1; i <= count; i++)
		{
			f32 theta;
			f32 dist;
			theta_x_z(&points[m], &points[i], &theta, &dist);

			if (theta < minAngle || dist <= 0.0f)
				continue;

			if (theta < best || (theta == best && !(dist <= bestDist)))
			{
				next = i;
				best = theta;
				bestDist = dist;
			}
		}

		if (next == count)
			return m + 1;

		angle = best;
	}

	return 0;
}

/* @socom-skeleton stub theta_x_z__Q23zdb7CCameraFP6CPnt3DP6CPnt3DPfPf */
/* @socom-skeleton stub theta_x_z__Q23zdb7CCameraFP6CPnt3DP6CPnt3DPfPf */
void zdb::CCamera::theta_x_z(CPnt3D *from, CPnt3D *to, float *theta, float *dist)
{
	/* 0x1e4e00: a pseudo-angle 0..4 of the x/z direction from -> to (with z negated) and
	   its taxicab length. ELF quirk kept: the length is summed in double (fabs). */
	f32 dx = to->x - from->x;
	f32 dz = from->z - to->z;
	f32 d = (f32)(fabs((double)dx) + fabs((double)dz));
	*dist = d;

	f32 t = d;

	if (d != 0.0f)
		t = dz / d;

	if (dx < 0.0f)
		t = 2.0f - t;
	else if (dz < 0.0f)
		t = 4.0f + t;

	*theta = t;
}

/* @socom-skeleton stub TestFOV__Q23zdb7CCameraFP5PNT4DPUib */
zdb::tag_ZVIS_FOV zdb::CCamera::TestFOV(PNT4D *corners, unsigned int *clipWord, bool guardBand)
{
	/* 0x1e4d20: clip the 8 bbox corners against mtxWorldToClip: out when every corner is
	   past one plane of m_fovMask's low byte, in when none straddles a plane of its high
	   byte; a straddling box is clipped only when guardBand and some corner leaves the
	   guard band (the GS scissor takes the rest) */
	unsigned int local;
	unsigned int* word = clipWord != NULL ? clipWord : &local;

	*word = sceVu0ClipBBox(m_mtxSet.mtxWorldToClip, corners);

	if (*word & (m_fovMask & 0x3f))
		return tag_ZVIS_FOV::ZVIS_FOV_ALL_OUT;

	if (!(*word & (m_fovMask & 0x3f00)))
		return tag_ZVIS_FOV::ZVIS_FOV_ALL_IN;

	if (!guardBand)
		return tag_ZVIS_FOV::ZVIS_FOV_ALL_IN;

	if (_OutsideGuardBand(m_guardBand_min, m_guardBand_max, m_mtxSet.m_vu->mtxWorldToScreen, reinterpret_cast<f32(*)[4]>(corners), 8))
		return tag_ZVIS_FOV::ZVIS_FOV_CLIP;

	return tag_ZVIS_FOV::ZVIS_FOV_ALL_IN;
}

/* @socom-skeleton stub SetCameraCanSeeRegions__Q23zdb7CCameraFUi */
void zdb::CCamera::SetCameraCanSeeRegions(unsigned int regions)
{
	/* 0x1e4cf0: a nonzero mask replaces the camera's regions */
	if (regions == 0)
		return;

	m_CameraCanSeeRegions = regions;
	m_SeeRegions = (m_PlayerCanSeeRegions | 1) | m_CameraCanSeeRegions;
}

/* @socom-skeleton stub SetPlayerCanSeeRegions__Q23zdb7CCameraFUi */
void zdb::CCamera::SetPlayerCanSeeRegions(unsigned int regions)
{
	/* 0x1e4cc0: a nonzero mask replaces the player's regions; region bit 0 is always seen */
	if (regions == 0)
		return;

	m_PlayerCanSeeRegions = regions;
	m_SeeRegions = (m_PlayerCanSeeRegions | 1) | m_CameraCanSeeRegions;
}

/* @socom-skeleton body CanSeeRegion__Q23zdb7CCameraFUi */
namespace zdb {
bool CCamera::CanSeeRegion(u32 mask)
	{
		/* 0x1e4c80: true without the region test (the earlier port returned false there),
		   else whether the seen regions meet the mask (0 means bit 0) */
		if (!mask)
			mask = 1;

		if (!m_do_region_test)
			return true;

		return (m_SeeRegions & mask) != 0;
	}
}

/* @socom-skeleton stub PlayerCanSeeRegion__Q23zdb7CCameraFUi */
