	          + (m_matrix.m_matrix[3][1] - pos.y) * m_matrix.m_matrix[2][1]
	          + (m_matrix.m_matrix[3][2] - pos.z) * m_matrix.m_matrix[2][2]; /* VU0 vsub/vmul + w sum */

