/* @socom-skeleton stub GetZ__Q23zdb7CCameraFP6CPnt3D */
float zdb::CCamera::GetZ(CPnt3D *point)
{
	/* 0x1e48a0: the view depth (position - point) . z axis (VU0 vsub/vmul and a w sum; the
	   unsquared GetScaledZSquared) */
	return (m_matrix.m_matrix[3][0] - point->x) * m_matrix.m_matrix[2][0]
	     + (m_matrix.m_matrix[3][1] - point->y) * m_matrix.m_matrix[2][1]
	     + (m_matrix.m_matrix[3][2] - point->z) * m_matrix.m_matrix[2][2];
}

/* @socom-skeleton stub GetScaledZSquared__Q23zdb7CCameraFP6CPnt3D */
float zdb::CCamera::GetScaledZSquared(CPnt3D *point)
{
	/* 0x1e4820: m_RangeScale times the squared view depth: ((position - point) . z axis)^2
	   (VU0 vsub/vmul and a w sum) */
	f32 d = (m_matrix.m_matrix[3][0] - point->x) * m_matrix.m_matrix[2][0]
	      + (m_matrix.m_matrix[3][1] - point->y) * m_matrix.m_matrix[2][1]
	      + (m_matrix.m_matrix[3][2] - point->z) * m_matrix.m_matrix[2][2];

	return d * d * m_RangeScale;
}

/* @socom-skeleton stub GetLandmarkFarPlane__Q23zdb7CCameraFPQ23zdb6CWorld */
/* @socom-skeleton stub GetLandmarkFarPlane__Q23zdb7CCameraFPQ23zdb6CWorld */
void zdb::CCamera::GetLandmarkFarPlane(zdb::CWorld *world)
{
	/* 0x1e4710 (CCoreState::Init): the landmark far plane reaches twice the largest
	   landmark radius, at least the grid's extent diagonal, and is 4 x the far plane
	   when that is farther */
	f32 maxRadiusSq = 0.0f;

	for (CNodeVector::iterator it = world->m_landmarks.begin(); it != world->m_landmarks.end(); ++it)
	{
		f32 radiusSq = (*it)->GetRadiusSq();

		if (!(radiusSq <= maxRadiusSq))
			maxRadiusSq = radiusSq;
	}

	m_landmark_far_plane = 2.0f * sqrtf(maxRadiusSq);

	CFRect& extents = world->m_grid->m_extents;
	f32 dx = extents.left - extents.right;
	f32 dz = extents.top - extents.bottom;
	f32 diagonal = sqrtf(dx * dx + dz * dz);

	if (!(diagonal <= m_landmark_far_plane))
		m_landmark_far_plane = diagonal;

	if (!(m_far_plane <= m_landmark_far_plane))
		m_landmark_far_plane = 4.0f * m_far_plane;
}

/* @socom-skeleton stub TestFOG__Q23zdb7CCameraFPC6CPnt3Df */
unsigned char zdb::CCamera::TestFOG(const CPnt3D *worldPos, float radius)
{
	/* 0x1e4610: below the fog top (altitude fog), or fogged when fogCheck is set and the
	   sphere reaches past m_fog_near in view depth. */
	bool fogged = m_fog_enabled != 0;
	bool below = false;

	if (fogged)
	{
		if (m_fog_alt_enabled)
			below = worldPos->y - radius < m_fog_top;

		f32 depth = (m_matrix.m_matrix[3][0] - worldPos->x) * m_matrix.m_matrix[2][0]
		          + (m_matrix.m_matrix[3][1] - worldPos->y) * m_matrix.m_matrix[2][1]
		          + (m_matrix.m_matrix[3][2] - worldPos->z) * m_matrix.m_matrix[2][2];

		if (radius + depth < m_fog_near)
			fogged = false;
	}

	return (below | (fogged & fogCheck)) != 0;
}

/* @socom-skeleton body TestLandmarkFOG__Q23zdb7CCameraFPC6CPnt3Df */
unsigned char zdb::CCamera::TestLandmarkFOG(const CPnt3D *pos, float radius)
	{
		bool canSee = false;

		if (m_fog_enabled)
		{
			canSee = false;

			if (m_directional_fog_enabled)
			{
				if (m_landmark_fog_top <= pos->y - radius)
					canSee = false;
			}

			CPnt3D& camPos = (CPnt3D&)(m_matrix(3, 0)); /* port: CMatrix has no operator[]; __cl__7CMatrixCFUiUi is emitted by this unit */
			CPnt3D out;
			pos->Sub(&camPos, &out);

			f32 dist = sqrtf((camPos.z * camPos.z) + (camPos.y * camPos.y) + (camPos.x * camPos.x));
			if (radius + dist < m_fog_near)
				canSee = false;
		}

		return canSee || (m_fog_enabled & fogCheck) != 0;
	}

